<script setup lang="ts">
import {ref,onMounted} from '#imports'
const props=defineProps<{csrfToken:string;zh:boolean}>(),items=ref<any[]>([]),name=ref(''),password=ref(''),role=ref('member'),busy=ref(false),problem=ref('')
async function load(){try{items.value=(await $fetch<any>('/transfer-api/v1/admin/accounts')).items}catch{problem.value=props.zh?'读取账号失败':'Unable to load accounts'}}
async function action(body:any){busy.value=true;problem.value='';try{items.value=(await $fetch<any>('/transfer-api/v1/admin/accounts',{method:'PUT',body,headers:{'x-csrf-token':props.csrfToken}})).items;name.value='';password.value=''}catch(e:any){problem.value=e.data?.error?.code==='FT_ACCOUNT_EXISTS'?(props.zh?'账号名称已存在':'Account already exists'):(props.zh?'操作失败，请检查输入；不能禁用自己。':'Check your input. You cannot disable yourself.')}finally{busy.value=false}}
onMounted(load)
</script>
<template><section id="ft-section-accounts" class="ft-panel"><h2>{{zh?'独立账号':'Local accounts'}}</h2><p class="ft-muted">{{zh?'管理员可管理此工具；传输权限仍由使用权限规则决定。成员角色 ID 为 member，管理员为 admin。':'Administrators manage this tool. Transfer permissions remain controlled by access rules. Role IDs: member / admin.'}}</p><div class="ft-account-list"><article v-for="item in items" :key="item.uid"><div><strong>{{item.name}}</strong><small>{{item.role}} · {{item.uid}}</small></div><button type="button" class="ft-button ft-secondary" :disabled="busy" @click="action({action:'disable',uid:item.uid,disabled:!item.disabled})">{{item.disabled?(zh?'启用':'Enable'):(zh?'禁用':'Disable')}}</button></article></div><form class="ft-create-account" @submit.prevent="action({action:'create',name,password,role})"><label class="ft-field">{{zh?'新账号':'New account'}}<input v-model="name" required maxlength="64" autocomplete="off"></label><label class="ft-field">{{zh?'初始密码（至少 6 位）':'Password (6+ characters)'}}<input v-model="password" type="password" required minlength="6" maxlength="256" autocomplete="new-password"></label><label class="ft-field">{{zh?'角色':'Role'}}<select v-model="role"><option value="member">{{zh?'成员':'Member'}}</option><option value="admin">{{zh?'管理员':'Administrator'}}</option></select></label><button class="ft-button" :disabled="busy">{{zh?'添加账号':'Add account'}}</button></form><p v-if="problem" role="alert">{{problem}}</p></section></template>
